@js:
if(baseUrl.match(/page=\d+/)){
n=parseInt(result.match(/max="([^"]+)"/)[1]);
m=result.match(/(\d+)\/(\d+)/);
a=result.match(/page=(\d+)/)[1];
c=parseInt(baseUrl.match(/page=(\d+)/)[1]);
b=baseUrl.match(/(https:\/\/estar.jp\/.*?\/\d+\/viewer\?page=)\d+/)[1];
