ruleContent.content:
@css:div.alert~div.panel div.panel-body@html||main p@html||html@lang||body h1@text
<js>
//书评|正文|无内容|卷名
if(String(chapter.url).endsWith("🍊")){chapter.title}
else if(result=="zh-hans"){"无人区，这里暂时没有书评呢(˃ ⌑ ˂ഃ )"}
else{result}
</js>

ruleContent.nextContentUrl:
nav@ul@li.-1@a@href
<js>
s=[];
r=String(result);
n=r.slice(r.lastIndexOf("/")+1,-1);
for(i=1;i<=n;i++){s.push(baseUrl+"/"+i)}
s
</js>

