@js:Cookie={}
args={}
baseUrl.match(/[^?=&]+=[^&]*/g).map(v=>{v=v.match(/(.+?)=(.*)/);if(v)args[v[1]]=v[2]})
curl=source.key+'/truyen/'+args.h+'/1/'+args.bookid+'/'+args.c+'/'
window={setInterval:function(){},addEventListener:function(a,b,c){},getCookie:function(name){return Cookie[name]}}
function split(s){
	s.split(';').map(v=>{v=v.match(/(.+?)=(.*)/);if(v)Cookie[v[1]]=v[2]})
}

c=source.getLoginHeaderMap()
c&&split(c.get('Cookie'))
function concat(o){
	return Object.entries(o).map(v=>v.join('=')).join('; ')
}
function updateCookie(){
	r=java.get(curl,{"Cookie":concat(Cookie)})
	split(concat(r.cookies()))
	_gac=r.body().match('_gac=.+?(?=;)')
	_gac&&split(_gac[0])
	_ac=r.body().match('_ac=.+?(?=;)')
	_ac&&split(_ac[0])
	!Cookie._ac&&updateCookie()
	String(r.body()).replace(/var ([\w\d]+?)\s*=\s*['"](.+?)['"]/g,function(a,name,value){this[name]=value})
	state=0
	eval(String(source.bookSourceComment))
	r=java.post(baseUrl,key,{"referer":String(curl),"cookie":concat(Cookie),"X-Requested-With":"XmlHttpRequest"})
	split(concat(r.cookies()))
	return concat(Cookie)
}
c=updateCookie()
html=java.post(baseUrl,'',{"referer":String(curl),"cookie":c,"Content-type":"application/x-www-form-urlencoded"}).body()
java.setContent(html)
result=String(java.getString('data||err')).replace(/<span.+?<\/span>/g,'').replace(/<div class=\s*.ad[\s\S]+?<\/div>/g,'')
// java.log(result)
result.replace(/ *<i .+?<\/i>/g,function(a){m=a.match(/h=.*?t='(.*?)'/);return m?m[1]:''}).replace(/.img\s*src\s*=\s*['"](.*?)['"]\s*\/./,'<img src="$1"/>')

source.loginJs:
function check(){
	h=java.ajax(source.key+'/user/0/')
	m=h.match(/dsname.+?>\s*(.+?)\s*</)
	if(m){
		java.longToast(m[1]+'登录成功')
	}else{
		java.longToast('登录失效')
	}
}
function login(register){
	info=source.getLoginInfoMap()
	n=info.用户名
	p=info.密码
	path='username='+n+'&psw='+p
	if(register){
		path='ajax=register&ngmar=regnick&'+path+'&repsw='+p
	}else{
		path='ajax=login&'+path
	}
	res=java.get(source.key+'/index.php?'+path,{})
	if(res.body()=='success'){
		if(register){
			java.longToast('注册成功')
		}
	 cookie=res.cookies()
	 source.putLoginHeader('{"Cookie":"PHPSESSID='+cookie.PHPSESSID+';access='+cookie.access+';lang=zh"}')
	}else{
		if(register){
			java.longToast('用户名"'+n+'"注册失败')
		}
		throw new Error(res.body())
	}
}

